beginning.embedded_functions:
#include <errno.h>
#include <pthread.h>
#include <sys/time.h>

#define EM_SYN_FLOOD_SLOTS 4096
#define EM_SYN_FLOOD_PROBES 8
#define EM_SYN_FLOOD_THRESHOLD_MAX 1000000000UL
#define EM_SYN_FLOOD_WINDOW_MS_MAX 3600000UL

static unsigned long em_syn_flood_threshold = 100;
static uint64_t      em_syn_flood_window_us = 1000 * 1000;

typedef struct {
	uint32_t ip;          //destination IPv4 address, network order
	uint16_t port;        //destination port
	uint8_t  used;
	uint64_t start_us;    //start of the current window
	unsigned long count;  //SYN counted in the current window
} em_syn_flood_slot_t;

static em_syn_flood_slot_t em_syn_flood_table[ EM_SYN_FLOOD_SLOTS ];
static pthread_mutex_t     em_syn_flood_lock = PTHREAD_MUTEX_INITIALIZER;

// Reads the environment variable name into *value: a decimal integer from 1 to max, without sign,
// leading zero or trailing character. Returns 1 when it is set, else 0. An invalid value leaves
// *value unchanged and gives a warning.
static int em_syn_flood_getenv( const char *name, unsigned long max, unsigned long *value ){
	const char *str = getenv( name ), *p;
	unsigned long v;
	char *end;

	if( str == NULL )
		return 0;
	for( p = str; *p >= '0' && *p <= '9'; p++ )
		;
	if( p != str && *p == '\0' && str[0] != '0' ){
		errno = 0;
		v = strtoul( str, &end, 10 );
		if( errno == 0 && *end == '\0' && v >= 1 && v <= max ){
			*value = v;
			return 1;
		}
	}
	mmt_warn( "Rule 57: ignored %s=\"%s\": expected a decimal integer from 1 to %lu; using the default %lu",
		name, str, max, *value );
	return 1;
}

void on_load(){
	unsigned long window_ms = em_syn_flood_window_us / 1000;
	int is_set = em_syn_flood_getenv( "MMT_SEC_SYN_FLOOD_THRESHOLD", EM_SYN_FLOOD_THRESHOLD_MAX, &em_syn_flood_threshold );
	is_set |= em_syn_flood_getenv( "MMT_SEC_SYN_FLOOD_WINDOW_MS", EM_SYN_FLOOD_WINDOW_MS_MAX, &window_ms );
	em_syn_flood_window_us = (uint64_t) window_ms * 1000;
	if( is_set )
		mmt_info( "Rule 57: SYN flood threshold: %lu SYN within %lu ms", em_syn_flood_threshold, window_ms );
}

//murmur3 finalizer: every input bit reaches every output bit
static inline uint32_t em_syn_flood_mix( uint32_t h ){
	h ^= h >> 16; h *= 0x85ebca6bu;
	h ^= h >> 13; h *= 0xc2b2ae35u;
	h ^= h >> 16;
	return h;
}

// Counts one SYN to (ip_dst, port) at time utime (struct timeval).
// Returns 1 when this SYN is the em_syn_flood_threshold-th one of the current window.
static inline int em_syn_flood_rate_reached( const void *ip_dst, double port, const void *utime ){
	const struct timeval *tv = (const struct timeval *) utime;
	em_syn_flood_slot_t *slot = NULL, *cand;
	uint32_t ip, hash;
	uint16_t p = (uint16_t) port;
	uint64_t now;
	int i, ret;

	if( ip_dst == NULL || tv == NULL )
		return 0;
	memcpy( &ip, ip_dst, 4 );
	now  = (uint64_t) tv->tv_sec * 1000000 + (uint64_t) tv->tv_usec;
	hash = em_syn_flood_mix( em_syn_flood_mix( ip ) ^ p );

	pthread_mutex_lock( &em_syn_flood_lock );
	//find the slot of this destination, or else the first free or expired slot
	for( i = 0; i < EM_SYN_FLOOD_PROBES; i++ ){
		cand = &em_syn_flood_table[ (hash + i) % EM_SYN_FLOOD_SLOTS ];
		if( cand->used && cand->ip == ip && cand->port == p ){
			slot = cand;
			break;
		}
		if( slot == NULL && ( !cand->used || now - cand->start_us > em_syn_flood_window_us ))
			slot = cand;
	}
	if( slot == NULL )
		slot = &em_syn_flood_table[ hash % EM_SYN_FLOOD_SLOTS ];

	//new destination in this slot, or its window is over: start a new window
	if( !slot->used || slot->ip != ip || slot->port != p || now - slot->start_us > em_syn_flood_window_us ){
		slot->used     = 1;
		slot->ip       = ip;
		slot->port     = p;
		slot->start_us = now;
		slot->count    = 0;
	}
	slot->count ++;
	ret = ( slot->count == em_syn_flood_threshold );
	pthread_mutex_unlock( &em_syn_flood_lock );
	return ret;
}
